INSERT INTO dbo.MonitoringProgram (MonitoringProgramID, MonitoringProgramName, MonitoringProgramCategoryID, MonitoringProgramDescription, MonitoringApproach, IsFeatured, Template, DashboardConfig) VALUES (46, N'Particulate Matter 2.5', 1, NULL, N'Particulate matter is monitored by Placer County in Tahoe City, and at LTCC and DL Bliss as part of the national IMPROVE national monitoring network.', 0, N'charts', N'{"measures":[{"title":"Fine particulate matter by station","sub":"Yearly fine particulate matter (PM2.5) statistic at each monitoring station, in micrograms per cubic meter. Choose a statistic.","layer":46,"where":"Pollutant = ''PM2.5''","x":"Year","y":"Value","yLabel":"PM2.5 (\u00b5g/m\u00b3)","seriesBy":"Site","seriesLabel":"Station","pick":"Indicator","pickLabel":"Statistic","pickDefault":"PM2.5 - ANNUAL AVG.","standard":{"field":"Threshold_Value"},"span":"span-12"},{"title":"Daily fine particulate matter by station","sub":"Daily fine particulate matter (PM2.5) values at each station from the daily monitoring record, in the units named in each statistic. Choose a statistic.","layer":17,"where":"variable LIKE ''PM 2.5%'' OR variable LIKE ''PM2.5%''","x":"date","xType":"date","xLabel":"Date","y":"value","yName":"PM2.5","yLabel":"PM2.5","seriesBy":"id","seriesLabel":"Station","seriesNames":{"STL":"Stateline","TC":"Tahoe City","IV":"Incline Village","SLT":"South Lake Tahoe","BSP":"DL Bliss State Park","LTC":"Lake Tahoe Community College"},"pick":"variable","pickLabel":"Statistic","span":"span-12"}],"sitesLayer":{"layer":16,"name":"name","code":"id","active":"Active_2023","unit":"station"},"sitesPerYear":{"layer":46,"year":"Year","site":"Site","where":"Pollutant = ''PM2.5''","unit":"station"}}');
INSERT INTO dbo.MonitoringProgram (MonitoringProgramID, MonitoringProgramName, MonitoringProgramCategoryID, MonitoringProgramDescription, MonitoringApproach, IsFeatured, Template, DashboardConfig) VALUES (45, N'Particulate Matter 10', 1, NULL, N'Particulate matter is monitored in the Tahoe Basin by the California Air Resources Board at South Lake Tahoe, and is monitored as part of the national IMPROVE network sites at LTCC and DL Bliss State Park.', 0, N'charts', N'{"measures":[{"title":"Particulate matter by station","sub":"Yearly particulate matter (PM10) statistic at each monitoring station, in micrograms per cubic meter. Choose a statistic.","layer":46,"where":"Pollutant = ''PM10''","x":"Year","y":"Value","yLabel":"PM10 (\u00b5g/m\u00b3)","seriesBy":"Site","seriesLabel":"Station","pick":"Indicator","pickLabel":"Statistic","pickDefault":"PM10 - ANNUAL AVG.","standard":{"field":"Threshold_Value"},"span":"span-12"},{"title":"Daily particulate matter by station","sub":"Daily particulate matter (PM10) values at each station from the daily monitoring record, in the units named in each statistic. Choose a statistic.","layer":17,"where":"variable LIKE ''PM 10%'' OR variable LIKE ''PM10%''","x":"date","xType":"date","xLabel":"Date","y":"value","yName":"PM10","yLabel":"PM10","seriesBy":"id","seriesLabel":"Station","seriesNames":{"STL":"Stateline","TC":"Tahoe City","IV":"Incline Village","SLT":"South Lake Tahoe","BSP":"DL Bliss State Park","LTC":"Lake Tahoe Community College"},"pick":"variable","pickLabel":"Statistic","span":"span-12"}],"sitesLayer":{"layer":16,"name":"name","code":"id","active":"Active_2023","unit":"station"},"sitesPerYear":{"layer":46,"year":"Year","site":"Site","where":"Pollutant = ''PM10''","unit":"station"}}');
INSERT INTO dbo.MonitoringProgram (MonitoringProgramID, MonitoringProgramName, MonitoringProgramCategoryID, MonitoringProgramDescription, MonitoringApproach, IsFeatured, Template, DashboardConfig) VALUES (63, N'Stream Bioassessment and Physical Habitat', 2, N'TRPA began monitoring perennial streams in 2009 to determine if TRPA thresholds for stream habitat are being met, and to detect changes in the overall condition of the Tahoe Basin''s streams. Bioassessment, which uses benthic macroinvertebrates (BMI) and physical stream habitat to assess overall stream health, is used to monitor the Basin''s streams. To obtain a stream health "score", the California Stream Condition Index (CSCI) is used. The CSCI is a model that compares the BMI found in sampled streams against the BMI expected to be found in pristine streams in the Sierra Nevada.
INSERT INTO dbo.MonitoringProgram (MonitoringProgramID, MonitoringProgramName, MonitoringProgramCategoryID, MonitoringProgramDescription, MonitoringApproach, IsFeatured, Template, DashboardConfig) VALUES (59, N'Scenic Monitoring', 4, NULL, N'Every four years, a team of professionals examines and evaluates the quality of
INSERT INTO dbo.MonitoringProgram (MonitoringProgramID, MonitoringProgramName, MonitoringProgramCategoryID, MonitoringProgramDescription, MonitoringApproach, IsFeatured, Template, DashboardConfig) VALUES (49, N'SEZ Basin-wide Monitoring and Assessment Plan', 5, N'The SEZ Basinwide Monitoring and Assessment Plan provides the methods and protocals to assess the current status and long-term trends of SEZs on a Basin-wide scale. The Plan will also provide a means to evaluate the impacts of ongoing and future management actions, identify regional impairments, and detect long-term trends that can inform sound future SEZ policy.', N'SEZ function is evaluated as a function of up to 10 indicators. Details on each indicator and monitoring methods are available in the plan.
INSERT INTO dbo.MonitoringProgram (MonitoringProgramID, MonitoringProgramName, MonitoringProgramCategoryID, MonitoringProgramDescription, MonitoringApproach, IsFeatured, Template, DashboardConfig) VALUES (39, N'Tahoe Yellow Cress Monitoring', 6, N'Tahoe Yellow Cress (TYC, Rorippa subumbellata) is a small native plant that grows on the shoreline of Lake Tahoe and no where else in the world. It lives only on the sandy beaches and dunes at the ever-changing margin of the lake. Impacts from recreation and development first led to conservation concerns in the 1970’s and TYC has been listed as endangered in both states since 1982. In 1999, a multi-agency and private interest group task force was formed to develop and implement a conservation strategy to promote the recovery and conservation of TYC. The conservation strategy provides an adaptive management framework and options for avoiding, minimizing, and mitigating impacts to TYC and its habitat on public and private lands. The TYC Stewardship Program recognizes the critical role of private landowners in ensuring the long-term survival of TYC.
INSERT INTO dbo.MonitoringProgram (MonitoringProgramID, MonitoringProgramName, MonitoringProgramCategoryID, MonitoringProgramDescription, MonitoringApproach, IsFeatured, Template, DashboardConfig) VALUES (83, N'Subalpine Conifer', 6, N'A monitoring program to track the non-degradation of subalpine conifer species, including the endangered whitebark pine.', N'Ground-based plot data that inform remote sensing techniques to track change over time in species composition, health, and distribution in the subalpine zone.', 0, N'context', NULL);
INSERT INTO dbo.MonitoringProgram (MonitoringProgramID, MonitoringProgramName, MonitoringProgramCategoryID, MonitoringProgramDescription, MonitoringApproach, IsFeatured, Template, DashboardConfig) VALUES (82, N'Harmful Algae Bloom (HAB) Monitoring', 7, N'What are Harmful Algal Blooms (HABs)?
INSERT INTO dbo.MonitoringProgram (MonitoringProgramID, MonitoringProgramName, MonitoringProgramCategoryID, MonitoringProgramDescription, MonitoringApproach, IsFeatured, Template, DashboardConfig) VALUES (15, N'LTIMP', 7, NULL, N'The Lake Tahoe Interagency Monitoring Program (LTIMP) stream monitoring program was first developed in 1979 to assess sediment and nutrient input from tributaries to Lake Tahoe, and to support research that aims to understand the drivers affecting the transparency of Lake Tahoe. The tributary monitoring focuses on both event-based conditions (large runoff events associated with rainfall and snowmelt) and baseline conditions (low inflow during summer when precipitation is negligible). Up to 10 streams have been monitored since the early 1990s; five in California (Upper Truckee River, and Trout, General, Blackwood and Ward Creeks) and five in Nevada (Third, Incline, Glenbrook, Logan House, and Edgewood Creeks). Six of these streams have been monitored since water years 1980 or 1981. In water year 2012 the number of streams routinely monitored was reduced to seven (see map above), and all streams have primary monitoring stations at or near the point of discharge to Lake Tahoe. Sampling pr', 0, N'map', N'{"measures":[{"title":"Suspended sediment","sub":"Annual average suspended sediment concentration across Lake Tahoe Interagency Monitoring Program (LTIMP) streams.","layer":85,"x":"Year","y":"AnnualAverage","yName":"Suspended sediment","yLabel":"Concentration"},{"title":"Total phosphorus","sub":"Annual average total phosphorus concentration across LTIMP streams.","layer":88,"x":"Year","y":"AverageTotalPhosphorousConcentr","yName":"Total phosphorus","yLabel":"Concentration"},{"title":"Total nitrogen","sub":"Annual average total nitrogen concentration across LTIMP streams.","layer":87,"x":"Year","y":"AverageTotalNitrogenConcentrati","yName":"Total nitrogen","yLabel":"Concentration","span":"span-12"},{"title":"Total phosphorus samples","sub":"Total phosphorus concentration in each sample, with the state standard for the site. Choose a site.","layer":100,"x":"SampleDate_Time","xType":"date","xLabel":"Sample date","y":"TotalPhosphorus","yName":"Total phosphorus","yLabel":"Concentration","pick":"SiteName","pickLabel":"Site","standard":{"field":"State_Standard","label":"State standard"},"span":"span-12"},{"title":"Total nitrogen samples","sub":"Total nitrogen concentration in each sample, with the state standard where the site has one. Choose a site.","layer":101,"x":"SampleDatetime","xType":"date","xLabel":"Sample date","y":"Total_Nitrogen","yName":"Total nitrogen","yLabel":"Concentration","pick":"SiteName","pickLabel":"Site","standard":{"field":"State_Standard","label":"State standard"},"span":"span-12"}],"sitesLayer":{"layer":33,"name":"station_nm","code":"site_no","unit":"station"},"sitesPerYear":{"layer":99,"year":"SampleDatetime","site":"SiteName","extract":true,"unit":"station"}}');
INSERT INTO dbo.MonitoringProgram (MonitoringProgramID, MonitoringProgramName, MonitoringProgramCategoryID, MonitoringProgramDescription, MonitoringApproach, IsFeatured, Template, DashboardConfig) VALUES (76, N'Nearshore Human Health, E. coli Monitoring', 7, N'The Nearshore Human Health monitoring program collects Escherichia Coli (E. coli) samples to help resource managers ensure Lake Tahoe’s waters remain safe for public recreation. Water quality samples are collected between June and September at many beaches around the lake. More information about the sampling program are available here. A safe to swim map depicting recently collected E. coli data is available here.', N'Water quality samples for E. coli are taken throughout the summer at popular beaches around Lake Tahoe. E. coli is an indicator of the presence of harmful pathogens or viruses associated with recent contamination by wastewater or other fecal contamination. Individuals who swim in or contact water with elevated levels of E. coli may be at risk of getting sick because of potential exposure to harmful pathogens or viruses associated with wastewater or other fecal contamination.', 1, N'context', NULL);
INSERT INTO dbo.MonitoringProgram (MonitoringProgramID, MonitoringProgramName, MonitoringProgramCategoryID, MonitoringProgramDescription, MonitoringApproach, IsFeatured, Template, DashboardConfig) VALUES (66, N'Pelagic Water Quality (Clarity)', 7, N'Lake clarity measurements have been taken continuously by UC Davis Tahoe Environmental Research Center (TERC) since 1968, when a white disk, called the Secchi disk, could be seen down to 102 feet. It is one of the longest, unbroken clarity records in the world. Secchi depth is the most widely used method of clarity measurement, and the values are consistent with laser-based measurements also taken by TERC researchers. Water transparency in Lake Tahoe is controlled by fine particles blocking light penetration either by scattering or by absorption. The decline in transparency is the result of accumplation of fine sediment particles and growth of small phytoplankton (algae). Fine sediments and nutirents are transporated to the lake by stormwater runoff, stream erosion, and through atmospheric deposition.', N'Measurements are taken in Lake Tahoe using a 25 centimeter, all white Secchi disk. The disk is lowered into the water column from a boat to a depth at which it is no longer visible by the observer, and then raised slowly until visible again. The midpoint of these two depths is called the Secchi depth. Between 18 and 37 individual Secchi depth measurements have been collected each year at an established index station.
INSERT INTO dbo.MonitoringProgram (MonitoringProgramID, MonitoringProgramName, MonitoringProgramCategoryID, MonitoringProgramDescription, MonitoringApproach, IsFeatured, Template, DashboardConfig) VALUES (13, N'Periphyton', 7, NULL, N'UC Davis has monitored periphyton in Lake Tahoe since 2000. Monitoring also occurred between 1982 and 1985 and 1989 to 1993. The primary periphyton monitoring work are regular sampling work referred to “routine” sampling at nine sites annually (the number of locations has varied historically from six to ten). At each location algal biomass (as chlorophyll a) is sampled five times annually from natural rock surfaces at a depth of 0.5 meters below the water level at the time of sampling. A second type of sampling, referred to a “synoptic” monitoring occurs once a year at 40 additional sites. The timing of synoptic monitoring varies annually and is intended to capture biomass at its peak in the spring. The synoptic monitoring includes collection of chlorophyll a at a sub-set of the sites, as well as a rapid assessment method that quantifies a periphyton biomass index (PBI).', 1, N'charts', N'{"measures":[{"title":"Periphyton at routine sites","sub":"Attached algae biomass as chlorophyll a, in milligrams per square meter. Choose a site.","layer":21,"x":"Date","xType":"date","xLabel":"Sample date","y":"value","yName":"Chlorophyll a","yLabel":"Chlorophyll a (mg/m\u00b2)","pick":"id","pickLabel":"Site","pickDefault":"Rubicon Point","span":"span-12"}],"sitesLayer":{"layer":102,"name":"SITE_NAME","status":"SiteClass"},"sitesPerYear":{"layer":21,"year":"Date","site":"id"}}');
INSERT INTO dbo.MonitoringProgram (MonitoringProgramID, MonitoringProgramName, MonitoringProgramCategoryID, MonitoringProgramDescription, MonitoringApproach, IsFeatured, Template, DashboardConfig) VALUES (16, N'Regional Stormwater Monitoring', 7, N'The Tahoe Resource Conservation District (Tahoe RCD) is leading the effort to measure pollutants in urban runoff at Lake Tahoe to help evaluate the combined effectiveness of pollutant control measures and consistently track and report monitoring findings. This effort, known as the Regional Storm Water Monitoring Program (RSWMP) is a collaborative program supported by regulatory agencies, local government representatives, and scientists in the Lake Tahoe region.
INSERT INTO dbo.MonitoringProgram (MonitoringProgramID, MonitoringProgramName, MonitoringProgramCategoryID, MonitoringProgramDescription, MonitoringApproach, IsFeatured, Template, DashboardConfig) VALUES (12, N'Nearshore Turbidity Monitoring', 7, NULL, N'A pilot monitoring program of nearshore turbidity began with the first circuit completed in November 2014, followed by similar nearshore circuits completed in April, June, August and November 2015. Measurements were made at a depth of seven meters. Routine boat operating speeds are typically around 10 kilometers per hour in the nearshore areas (Heyvaert et al., 2016). Beginning 1991, nearshore turbidity was measured offshore at the 25-meter depth contour for several locations, including 1) mouth of Upper Truckee River and Trout Creek; 2) El Dorado Beach; 3) mouth of Edgewood Creek; 4) Nevada Beach; 5) mouth of Incline Creek; 6) Burnt Cedar Beach; 7) mouth of Ward Creek; 8) Tahoe State Recreation Area; and 9) the mouth of Blackwood Creek. More recently, nearshore clarity has been measured at approximately the seven-meter contour following a continuous circuit around the lakeshore. This strategy is considered more representative of littoral conditions where people interact with the lake', 0, N'charts', N'{"measures":[{"title":"Nearshore turbidity by location","sub":"Turbidity in nephelometric turbidity units (NTU) at each nearshore location, by year.","layer":111,"x":"Year","y":"value","unpivot":{"prefix":"NTU"},"yName":"Turbidity","yLabel":"Turbidity (NTU)","seriesBy":"Location","seriesLabel":"Location","span":"span-12"},{"title":"Turbidity at one location","sub":"Turbidity in NTU each year at one nearshore location. Choose a location.","layer":111,"x":"Year","y":"value","unpivot":{"prefix":"NTU"},"yName":"Turbidity","yLabel":"Turbidity (NTU)","type":"bar","pick":"Location","pickLabel":"Location","span":"span-12"}]}');
INSERT INTO dbo.MonitoringProgram (MonitoringProgramID, MonitoringProgramName, MonitoringProgramCategoryID, MonitoringProgramDescription, MonitoringApproach, IsFeatured, Template, DashboardConfig) VALUES (14, N'Aquatic Invasive Plants', 7, NULL, N'Monthly veliger surveys for mussel larvae are done during the boating season.', 0, N'map', N'{"measures":[{"title":"Invasive plant acres by location","sub":"Acres of Eurasian watermilfoil and curlyleaf pondweed at each location.","layer":95,"x":"Location","xType":"category","xLabel":"Location","y":[{"field":"Eurasian_Watermilfoil","name":"Eurasian watermilfoil"},{"field":"Curlyleaf_Pondweed","name":"Curlyleaf pondweed"}],"yLabel":"Acres","type":"stacked","orientation":"h","sort":"desc","span":"span-12"},{"title":"Control sites by status","sub":"Aquatic invasive plant control sites by threshold status in 2023.","layer":114,"x":"Threshold_Status_2023","xType":"category","xLabel":"Status","y":"OBJECTID","stat":"count","yName":"Sites","yLabel":"Sites","type":"bar"},{"title":"Control sites by infestation status","sub":"Aquatic invasive plant control sites by infestation status code in 2024.","layer":114,"x":"Infest_Status_2024","xType":"category","xLabel":"Infestation status (2024)","y":"OBJECTID","stat":"count","yName":"Sites","yLabel":"Sites","type":"bar"}],"sitesLayer":{"layer":114,"name":"Site_Name","status":"Threshold_Status_2023"}}');
INSERT INTO dbo.MonitoringProgram (MonitoringProgramID, MonitoringProgramName, MonitoringProgramCategoryID, MonitoringProgramDescription, MonitoringApproach, IsFeatured, Template, DashboardConfig) VALUES (9093, N'Watercraft Inspections', 7, N'Watercraft inspected for aquatic invasive species before launching at Lake Tahoe each year, how many needed decontamination, and where the inspection stations are.', NULL, 0, N'charts', N'{"measures":[{"title":"Watercraft inspected","sub":"Watercraft inspected each year, by whether they needed decontamination.","layer":93,"x":"Year","y":[{"field":"Watercraft_Decontaminated","name":"Decontaminated"},{"field":"No_Decontamination_Necessary","name":"No decontamination needed"}],"yLabel":"Watercraft","type":"stacked","span":"span-12"}],"sitesLayer":{"layer":103,"name":"STATION_NAME","status":"STATION_TYPE","unit":"station"}}');
INSERT INTO dbo.MonitoringProgram (MonitoringProgramID, MonitoringProgramName, MonitoringProgramCategoryID, MonitoringProgramDescription, MonitoringApproach, IsFeatured, Template, DashboardConfig) VALUES (78, N'Aquatic Plant Survey Zones', 7, N'The Aquatic Plant Monitoring Program (APMP) is intended to gather, analyze, and report information relative to aquatic plant populations in Lake Tahoe, with an emphasis on collecting data that can be used to guide control efforts for aquatic invasive plant', N'Two levels of aquatic plant survey effort (spatial design) are applied to the APMP and each is performed on a different temporal scale. Once every five years a nearshore-wide aquatic plant survey is conducted via interpretation and mapping of remotely sensed data in combination with in situ diver sampling. Annually, only an in situ diver survey (or a reasonable surrogate) is performed following targeted and a stratified systematic sampling of transect lines with incorporated quadrats. The nearshore-wide aquatic plant survey (i.e., the combination of remote sensing imagery analysis with diver surveys) attempts to provide for a “baseline” status quantification of all aquatic plant beds around Lake Tahoe’s nearshore zone. The transect surveys allows for training and validation of remotely sensed data, and annual surveillance to establish trend information and the detection of new infestations of aquatic invasive plants. The sampling frame (i.e., survey area) and habitat stratification scheme used for line-transect surveys conducted in intervening years will be the same as that used for the nearshore-wide survey. Four habitat strata are used to divide the aquatic plant population into meaningful sampling units, including open-water nearshore, marshes, major tributaries, and marinas and embayments.', 0, N'map', N'{"measures":[{"title":"Survey zone acres by stratum","sub":"Acres of aquatic vegetation survey zones in each stratum.","layer":42,"x":"Strata","xType":"category","xLabel":"Stratum","y":"Acres","stat":"sum","yName":"Acres","yLabel":"Acres","type":"bar"},{"title":"Survey zones by stratum","sub":"Number of aquatic vegetation survey zones in each stratum.","layer":42,"x":"Strata","xType":"category","xLabel":"Stratum","y":"OBJECTID","stat":"count","yName":"Survey zones","yLabel":"Survey zones","type":"bar"}],"mapLayer":{"layer":42,"title":"Aquatic vegetation survey zones","unit":"survey zone","unitPlural":"Survey zones","name":"Location_1","colorBy":"Strata","colorByLabel":"Stratum","colors":{"Marina/Embayment":"#3e72b0","Nearshore Open Water":"#5a9cb0","Marsh":"#89bf40","Mrash":"#89bf40","Stream":"#e49937"},"labels":{"Mrash":"Marsh (recorded as Mrash)"},"meta":[{"field":"Strata"},{"field":"Acres","suffix":" acres"}],"fields":[{"field":"Strata","label":"Stratum"},{"field":"Acres","label":"Acres"},{"field":"Orient","label":"Orientation"}]}}');
INSERT INTO dbo.MonitoringProgram (MonitoringProgramID, MonitoringProgramName, MonitoringProgramCategoryID, MonitoringProgramDescription, MonitoringApproach, IsFeatured, Template, DashboardConfig) VALUES (9034, N'Submerged Aquatic Vegetation', 7, N'Mapped patches of targeted submerged aquatic vegetation in Lake Tahoe.', NULL, 0, N'map', N'{"mapLayer":{"layer":34,"title":"Targeted submerged aquatic vegetation","unit":"vegetation patch","unitPlural":"Vegetation patches","list":false,"countAsSites":false,"fields":[{"field":"Type","label":"Type"}]}}');
INSERT INTO dbo.MonitoringProgram (MonitoringProgramID, MonitoringProgramName, MonitoringProgramCategoryID, MonitoringProgramDescription, MonitoringApproach, IsFeatured, Template, DashboardConfig) VALUES (2, N'Osprey', 8, NULL, N'A shoreline survey is conducted by boat monthly during spring and summer months following standard protocols. Additional surveys are conducted at historic and likely nest sites at other lakes and upland areas. All suitable nesting habitat is surveyed for nest activity and nest success.', 0, N'charts', N'{"measures":[{"title":"Active osprey nests","sub":"Active nests counted each year, with the threshold.","layer":96,"where":"Wildlife_Species = ''Osprey''","x":"Year","y":"Total","yName":"Active nests","yLabel":"Active nests","type":"bar","span":"span-12","standard":{"field":"Threshold_Value"}}]}');
INSERT INTO dbo.MonitoringProgram (MonitoringProgramID, MonitoringProgramName, MonitoringProgramCategoryID, MonitoringProgramDescription, MonitoringApproach, IsFeatured, Template, DashboardConfig) VALUES (4, N'Bald Eagle', 8, NULL, N'Known nest sites are visited regularly during the incubation and fledging periods to determine reproductive success. Monthly boat surveys during non-winter months are conducted to identify any new nest sites surrounding Lake Tahoe, and ad-hoc surveys are conducted in other areas in support of environmental assessments for proposed projects.', 0, N'charts', N'{"measures":[{"title":"Active bald eagle nests","sub":"Active nests counted each year, with the threshold.","layer":96,"where":"Wildlife_Species = ''Bald Eagle - nesting''","x":"Year","y":"Total","yName":"Active nests","yLabel":"Active nests","type":"bar","standard":{"field":"Threshold_Value"}},{"title":"Wintering bald eagles","sub":"Individuals counted each year.","layer":96,"where":"Wildlife_Species = ''Bald Eagle - winter''","x":"Year","y":"Total","yName":"Individuals","yLabel":"Individuals","type":"bar"}]}');
INSERT INTO dbo.MonitoringProgram (MonitoringProgramID, MonitoringProgramName, MonitoringProgramCategoryID, MonitoringProgramDescription, MonitoringApproach, IsFeatured, Template, DashboardConfig) VALUES (6, N'Peregrine Falcon', 8, NULL, N'Biologists observe historic or potential nest sites for a minimum of four hours per month, April through August following standard U.S. Forest Service protocol. All potential nesting habitat is surveyed and incidental sighting are used to help focus monitoring efforts.', 0, N'charts', N'{"measures":[{"title":"Active peregrine falcon nests","sub":"Active nests counted each year, with the threshold.","layer":96,"where":"Wildlife_Species = ''Peregrine Falcon''","x":"Year","y":"Total","yName":"Active nests","yLabel":"Active nests","type":"bar","span":"span-12","standard":{"field":"Threshold_Value"}}]}');
INSERT INTO dbo.MonitoringProgram (MonitoringProgramID, MonitoringProgramName, MonitoringProgramCategoryID, MonitoringProgramDescription, MonitoringApproach, IsFeatured, Template, DashboardConfig) VALUES (29, N'Northern Goshawk', 8, NULL, N'Portions of known and potential northern goshawk habitat are surveyed following well-accepted protocols including a combination of dawn acoustic surveys, stand search surveys, and broadcast surveys. Recent survey work has been conducted in response to proposed projects and has been primarily focused at assessment of project level impacts, not assessment of population status and trends in the Tahoe Basin. The last full population survey was completed in 2010.', 0, N'charts', N'{"measures":[{"title":"Reproductively active goshawk territories","sub":"Active territories counted each year, with the threshold.","layer":96,"where":"Wildlife_Species = ''Northern Goshawk''","x":"Year","y":"Total","yName":"Active territories","yLabel":"Active territories","type":"bar","span":"span-12","standard":{"field":"Threshold_Value"}}]}');
INSERT INTO dbo.MonitoringProgram (MonitoringProgramID, MonitoringProgramName, MonitoringProgramCategoryID, MonitoringProgramDescription, MonitoringApproach, IsFeatured, Template, DashboardConfig) VALUES (7, N'Waterfowl', 8, NULL, N'The methodologies and indicators used by TRPA to evaluate the attainment status of the waterfowl standard has varied over time. The 2001 Threshold Evaluation Report used observed bird species richness and diversity along with the human activity rating system to gage threshold standard attainment status (TRPA 2001). The 2006 Threshold Evaluation Report used observation of bird species richness and diversity as well as an assessment of detrimental or non-native species, but did not use the human disturbance rating system that was used in 2001. The 2011 Threshold Evaluation Report used only a human disturbance rating system as a means to measure status (TRPA 2012a). Since 2015, the assessment method used is based on field observations and human activity levels at mapped waterfowl population sites, similar to the 2011 Threshold Evaluation Report methods. No formal waterfowl surveys were conducted. Each site was visited by a qualified observor to conduct the human disturbance rating evaluation.', 0, N'charts', N'{"measures":[{"title":"Average human activity rating","sub":"Average human activity rating score across waterfowl sites, by survey year.","layer":96,"where":"Wildlife_Species = ''Waterfowl''","x":"Year","y":"Total","yName":"Average rating","yLabel":"Human activity rating","type":"bar"},{"title":"Human activity rating by site","sub":"Human activity rating at each waterfowl site, by survey year. Choose a site.","layer":94,"x":"Year","y":"value","unpivot":{"prefix":"F"},"yName":"Rating","yLabel":"Human activity rating","type":"bar","pick":"Name","pickLabel":"Site"}]}');
INSERT INTO dbo.MonitoringProgram (MonitoringProgramID, MonitoringProgramName, MonitoringProgramCategoryID, MonitoringProgramDescription, MonitoringApproach, IsFeatured, Template, DashboardConfig) VALUES (65, N'Noise - Highways', 9, N'TRPA regularly monitors noise along highway corridors in the Lake Tahoe Basin to ensure noise limits are not being exceeded. Because noise from highways is the largest source of background noise in the Basin, noise limits near highways ensures the serenity of the Tahoe Basin is maintained. High noise levels can reduce the public’s enjoyment of the natural environment, impact quality of life for residents, and disturb native wildlife.
INSERT INTO dbo.MonitoringProgram (MonitoringProgramID, MonitoringProgramName, MonitoringProgramCategoryID, MonitoringProgramDescription, MonitoringApproach, IsFeatured, Template, DashboardConfig) VALUES (61, N'Noise - Plan Areas', 9, N'TRPA monitors background noise levels in all Plan Areas in the Tahoe Basin to ensure noise levels are not disturbing people and wildlife, and to maintain the unique characteristics of the Basin. Each Plan Area has its own allowable noise level in TRPA''s thresholds, with maximum average 24-hour allowable noise levels ranging from 45 decibles (dB) in wilderness areas to 65 dB in industrial areas. High noise levels can reduce the public’s enjoyment of the natural environment, impact quality of life for residents, and disturb native wildlife.
INSERT INTO dbo.MonitoringProgram (MonitoringProgramID, MonitoringProgramName, MonitoringProgramCategoryID, MonitoringProgramDescription, MonitoringApproach, IsFeatured, Template, DashboardConfig) VALUES (62, N'Noise - Shorezone', 9, N'TRPA regularly monitors noise from motorized watercraft in the shorezone of Lake Tahoe to ensure noise levels are not being exceeded. Shorezone noise limits are in place to maintain the serenity of Lake Tahoe and to protect sensitive wildlife.', N'TRPA regulalry monitors noise in the shorezone from motorized watercraft at up to ten locations around Lake Tahoe. Noise monitors are deployed for at least two weeks during peak boating season which occurs July 4th to Labor Day. Noise monitors automatically record all single noise events that exceed 75 decibles (dB), the noise limit for shorezone areas. Afterward, all noise events exceeding 75 dB are listened to by a noise technician to distinguish noise exceedancs from watercraft and non-watercraft. Noise monitors are regularly calibrated to industry standards to ensure accuracy.
INSERT INTO dbo.MonitoringProgram (MonitoringProgramID, MonitoringProgramName, MonitoringProgramCategoryID, MonitoringProgramDescription, MonitoringApproach, IsFeatured, Template, DashboardConfig) VALUES (33, N'Bicycle and Pedestrian', 10, N'TRPA and local partners monitor bicycle and pedestrian activity throughout the Region to understand high use areas, mode-split, and support grant applications and reporting. Count information also informs policies and programs targeted to improve and support active transportation.', N'In 2015, as part of the update to the Active Transportation Plan, TRPA developed the Lake Tahoe Region Bicycle and Pedestrian Monitoring Protocol using best industry practices and national experts Kittleson & Associates. TRPA began implementation in summer of 2015, which built on and integrated previous monitoring efforts. In partnership with local agencies, TRPA has established a system for the collection of year-round active transportation data which includes permanent counting stations, biennial count locations, and spot count locations depending on need. During the first two years of implementation, TRPA produced a bicycle and pedestrian monitoring report which analyzes historical trends, provides detailed information by location, and compares use at similar sites. This report also supplemented the regional transportation monitoring report. Moving forward, all analysis and up-to-date data will be available on the transportation monitoring dashboard, in lieu of a hardcopy report.
INSERT INTO dbo.MonitoringProgram (MonitoringProgramID, MonitoringProgramName, MonitoringProgramCategoryID, MonitoringProgramDescription, MonitoringApproach, IsFeatured, Template, DashboardConfig) VALUES (77, N'Congestion-Travel Time', 10, N'TRPA monitors congestion on roadways throughout the region to assist with regional transportation planning. A well executed transportation management system incorporates monitoring data, real-time information, and dynamic operations that respond to seasonal congestion and periodic congestion.', N'Congestion can be characterized by many metrics and sourced from a variety of different data sources. For the purpose of analyzing congestion in the Tahoe region, TRPA uses the Regional Integrated Transportation Information System (RITIS) probe data analytics suite, provided by the Federal Highway Administration.
INSERT INTO dbo.MonitoringProgram (MonitoringProgramID, MonitoringProgramName, MonitoringProgramCategoryID, MonitoringProgramDescription, MonitoringApproach, IsFeatured, Template, DashboardConfig) VALUES (34, N'Safety', 10, N'Safety is a regional transportation plan goal and policy because it is critical that everyone feel comfortable traveling at Lake Tahoe, whether they are walking, taking the bus, riding a bike or driving a car. Safety is not only an important goal for Tahoe, the Federal Highway Administration (FHWA) recently established five safety performance measures. FHWA Safety (PM 1) Final Rule, effective April 14, 2016, supported the data-driven performance focus of the Highway Safety Improvement Program and established performance measures for which states and Metropolitan Planning Organizations must develop targets.', N'Safety performance measures help to assess fatalities and serious injury on all public roads regardless of ownership or functional classification. These measures are required to be incorporated into the regional transportation plan and state’s Highway Safety Improvement Programs. To support meeting these targets, a Lake Tahoe Region Safety Plan is underdevelopment which outlines crash trends, risk factors, gaps in data, and recommends strategies and designs to improve safety for all roadway users. Crash data is provided by the state of California and Nevada and consolidated by TRPA.
INSERT INTO dbo.MonitoringProgram (MonitoringProgramID, MonitoringProgramName, MonitoringProgramCategoryID, MonitoringProgramDescription, MonitoringApproach, IsFeatured, Template, DashboardConfig) VALUES (68, N'Socio-Economic', 10, N'TRPA monitors socio-economic data for a variety of purposes, including regional transportation planning, development rights, travel demand modeling, and sustainability. The U.S. Census Bureau is one important source of socioeconomic and demographic data.', N'The U.S. Census Bureau collects and distributes data under a handful of different programs. Two of the more commonly used programs are the Decennial Census and the American Community Survey (ACS). The Decennial Census is a definite source of demographic data but only is collected every ten years; it includes a limited number of variables such as number of households and total population. The ACS is a program that provides data estimates on a one, three, and five year timeline; ACS data is collected more frequently but the data estimates have a margin of error that must considered because the data is taken from a small sample of the total population. The ACS includes many more variables compared to the Decennial Census that relate to transportation, income, and housing. Both the Decennial and ACS datasets have similiar data structures. Each row in both datasets include a particular variable and a number the indicates the total number of households or persons that characterize that variable.', 1, N'context', NULL);
INSERT INTO dbo.MonitoringProgram (MonitoringProgramID, MonitoringProgramName, MonitoringProgramCategoryID, MonitoringProgramDescription, MonitoringApproach, IsFeatured, Template, DashboardConfig) VALUES (64, N'Traffic Volumes', 10, N'In partnership with the state DOTs, TRPA collects, monitors, and analyzes roadway traffic volume data from several dozen count stations throughout the Tahoe region.', N'Traffic volume monitoring is part of a regional strategy to create a well executed transportation management system that incorporates monitoring data, real-time information, and dynamic operations that respond to seasonal and periodic congestion. Over the last few years, intelligent transportation systems have seen significant advancements and deployments in the areas of data collection, data sharing, mobile solutions, and traffic monitoring capabilities. Both the California Department of Transportation (Caltrans) and the Nevada Department of Transportation (NDOT) manage several dozen permanent traffic count stations, which collect data on the number of vehicles traveling throughout the region. TRPA aggregates and analyzes this data for a variety of purposes, including project planning, development of our Regional Transportation Plan, and travel demand modeling.
INSERT INTO dbo.MonitoringProgram (MonitoringProgramID, MonitoringProgramName, MonitoringProgramCategoryID, MonitoringProgramDescription, MonitoringApproach, IsFeatured, Template, DashboardConfig) VALUES (36, N'Transit', 10, N'TRPA conducts on-going monitoring to inform transportation policy and programs with the goal of providing a successful multi-modal transportation system that appeals to users, supports mobility needs, and decreases dependency on the private automobile. TRPA has been monitoring transportation performance since the early 1970s including traffic counts, travel mode choice, and demographic and air quality trends so that planners can evaluate the Lake Tahoe Region’s transportation system and use best available science to inform policy-making. The 2016 FAST Act requires states and MPOs to develop targets for specific performance measures related to safety, transit, and roadway/bridge conditions. To comply with FAST Act regulations, TRPA has prioritized identifying performance measures and setting targets for transit to help transit agencies improve the efficiency and effectiveness of the level of service they provide in Tahoe.', N'TTD, TRPA, and TART work together in corridor and transit planning. Consistent transit rider surveys and operations data collection help determine the need for additional services and operating hours. Based on reporting requirements, TRPA''s Productivity Improvement Program (PIP), and goals outlined in the Regional Transportation Plan, Long Range Transit Master Plan, and each transit agency''s Short Range Transit Plans, the Tahoe transit monitoring program is built to track the following: Deadhead Miles and Hours, Ridership, Transit Mode Share, Productivity, On Time Performance, Operating Cost, Farebox Recovery, Rolling Stock, Equipment, Facilities, and Infrastructure. To find out more about these performance measures, take a look at the Tahoe Transit Monitoring Program: Monitoring Protocol.', 1, N'charts', N'{"measures":[{"title":"Transit routes by provider","sub":"Routes in the consolidated Tahoe transit route layer, by operator.","layer":2,"x":"PROVIDER","xType":"category","xLabel":"Provider","y":"OBJECTID","stat":"count","yName":"Routes","yLabel":"Routes","seriesBy":"SEASON","seriesLabel":"Season","type":"stacked","span":"span-12"}],"mapLayer":{"layer":2,"title":"Transit routes","unit":"route","unitPlural":"Routes","name":"ROUTE_NAME","geometry":"line","colorBy":"PROVIDER","colorByLabel":"Provider","colors":{"TART":"#3e72b0","TTD":"#e49937","SSTMA":"#89bf40"},"meta":[{"field":"PROVIDER"},{"field":"SEASON"}],"fields":[{"field":"ROUTE_NUMBER","label":"Route"},{"field":"PROVIDER","label":"Provider"},{"field":"SEASON","label":"Season"},{"field":"Frequency","label":"Frequency"},{"field":"WEBSITE","label":"Website"}]}}');
INSERT INTO dbo.MonitoringProgram (MonitoringProgramID, MonitoringProgramName, MonitoringProgramCategoryID, MonitoringProgramDescription, MonitoringApproach, IsFeatured, Template, DashboardConfig) VALUES (69, N'Travel Behavior', 10, N'Since 2006 TRPA has conducted basin-wide travel surveys every two years in order to better understand basic travel characteristics of both residents and visitors. The data collected - which includes data points such as mode share, origin-destinations, and trip purpose - is used for a variety of purposes at TRPA including regional performance metrics, project planning, and travel demand modelling.', N'The dashboard below summarises TRPA''s 2018 Summer Travel Survey, which was conducted in late-August of 2018.', 1, N'charts', N'{"measures":[{"title":"Vehicle miles traveled","sub":"Estimated vehicle miles traveled (VMT) in the Tahoe Region.","layer":92,"x":"Year","y":"VMT","yName":"VMT","yLabel":"Vehicle miles traveled","span":"span-12"}]}');
